func:
// see https://core.telegram.org/method/messages.sendMessage

// Only new messages. The receiver can emit deleted messages, albums, callback queries and raw
// updates as well, and none of those carries msg.payload.message - reaching into it regardless is
// how this used to fail with "Cannot read properties of undefined (reading 'className')" on every
// update. msg.payload.type is what tells the shapes apart.
if (msg.payload.type === 'NewMessage') {
    // A photo or a sticker with no caption has no text to echo, and Telegram rejects an empty one
    // with MESSAGE_EMPTY.
    let text = msg.payload.message.message;

    // chat is the resolved entity and the better peer, but getChat() comes back empty when this
    // session holds no access hash for the chat - and SendMessage then fails with the unhelpful
    // "Cannot cast undefined to any kind of undefined". peerId is on every message.
    let peer = msg.payload.chat || msg.payload.message.peerId;

    if (text !== '' && text !== undefined && text !== null && peer) {
        let randomId = BigInt(Math.floor(Math.random() * 1e15));

        msg.payload = {
            api: 'messages',
            func: 'SendMessage',
            args: {
                peer: peer,
                message: text,
                randomId: randomId,
                noWebpage: true,
                noforwards: true,
                scheduleDate: 0,
                // sendAs: "username",
            }
        }
        return msg;
    }
}
